function curlText(url) { return plainText(execFileSync('curl', ['-L', '-sS', '-A', 'Mozilla/5.0', url], {encoding: 'utf8', maxBuffer: 12 * 1024 * 1024})) }
async function fetchBuffer(url, attempts = 4) {
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    const response = await fetch(url, {headers: {'user-agent': 'BahaBuddyResearch/1.0 (content-ops@bahabuddy.com)'}})
    if (response.ok) return Buffer.from(await response.arrayBuffer())
    if (response.status !== 429 || attempt === attempts) throw new Error(`Image source failed: ${url} (${response.status})`)
    await new Promise((resolve) => setTimeout(resolve, attempt * 1500))
  }
  throw new Error(`Image source failed after retries: ${url}`)
}
async function fetchManagedBuffers() {
  const assets = []
  for (const definition of Object.values(managedAssetDefinitions)) {
    assets.push({...definition, buffer: await fetchBuffer(definition.url)})
    await new Promise((resolve) => setTimeout(resolve, 350))
  }
  return assets
}
