  return {_type: 'placeContentReadinessReview', checkedAt, nextReviewAt: nextOperationalReviewAt, overallStatus: 'blocked', accessibilityEvidenceStatus: 'not_found_in_reviewed_sources', accessibilitySources: references(ids, 'content-source'), accessibilityBoundary: 'Access mode, terrain, a boat requirement, stairs, a trail, or source silence does not establish feature-level accessibility. Missing evidence is not proof that a feature is inaccessible.', copyFoundationStatus: foundation, copyComponents: components, mediaEvidenceStatus: 'no_candidate_media', mediaRightsStatus: 'unknown_or_unverified', mediaPolicySources: [reference(sourceIds.mediaBoundary, 'media-policy-source')], altTextStatus: 'no_approved_image', publicCopyDecision: 'blocked', notes}
