  const point = !hasPoint ? 'no usable coordinate' : `${row.latitude}, ${row.longitude}`
  planned.catalogReviewNotes = foreign
    ? `Supabase row ${row.id} is assigned to Inagua, but its name, address, or point (${point}) identifies Hawaii, New Providence, Mallorca, Florida, Grand Bahama, or Argentina. Keep it inactive and channel-free; a data operator must quarantine, correct, or reassign it after source review.`
    : placeholder
